def lmark(g):
    cands=[(c,cells) for c,cells in comps2(g) if len(cells)>=9]
    # pick corner-shaped: bbox >=5 in one dim, cells form an L (corner + two arms)
    def isL(cells):
        ys=[y for y,x in cells]; xs=[x for y,x in cells]
        return (max(ys)-min(ys)>=4) and (max(xs)-min(xs)>=4) and len(cells)<= (max(ys)-min(ys)+1)+(max(xs)-min(xs)+1)-1
    Ls=[(c,cells) for c,cells in cands if isL(cells)]
    return max(Ls,key=lambda t:len(t[1])) if Ls else None
