    objs=[(c,cells) for c,cells in comps2(g) if len(cells)>1]
    d=defaultdict(list)
    for c,cells in objs: d[norm(cells)].append((c,cells))
    dups=[v for v in d.values() if len(v)>1]
    pair=max(dups,key=lambda v:len(v[0][1]))
    def dist(cells):
        return min(min(abs(y-ly)+abs(x-lx) for ly,lx in L[1]) for y,x in cells)
    tgt=max(pair,key=lambda t:dist(t[1]))
